<?php
declare(strict_types=1);namespace LittyWatch\Controllers;use LittyWatch\Core\{Request,Response,View};use LittyWatch\Repositories\PlatformRepository;use LittyWatch\Support\ProjectPaths;final class AssetController{public function __construct(private readonly PlatformRepository $repo,private readonly ProjectPaths $paths,private readonly View $view){}public function index(Request $r):Response{$dir=$this->paths->root('assets/game-items');$files=is_dir($dir)?glob($dir.'/*')?:[]:[];return Response::html($this->view->render('assets/index',['title'=>'Game assets · LittyWatch','count'=>count($files),'dbCount'=>$this->repo->counts()['item_assets']??0,'directory'=>$dir]));}}